import{_ as e,o as a,c as d,a4 as s}from"./chunks/framework.vNSRaLQv.js";const g=JSON.parse('{"title":"微服务抽取路线图：从胖单体到 ARM 集群","description":"","frontmatter":{"title":"微服务抽取路线图：从胖单体到 ARM 集群","date":"2026-08-16T00:00:00.000Z"},"headers":[],"relativePath":"posts/microservice-extraction-roadmap.md","filePath":"posts/microservice-extraction-roadmap.md"}'),n={name:"posts/microservice-extraction-roadmap.md"};function o(r,t,i,c,l,p){return a(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="微服务抽取路线图-从胖单体到-arm-集群" tabindex="-1">微服务抽取路线图：从胖单体到 ARM 集群 <a class="header-anchor" href="#微服务抽取路线图-从胖单体到-arm-集群" aria-label="Permalink to &quot;微服务抽取路线图：从胖单体到 ARM 集群&quot;">​</a></h1><h2 id="_0-架构原则" tabindex="-1">0. 架构原则 <a class="header-anchor" href="#_0-架构原则" aria-label="Permalink to &quot;0. 架构原则&quot;">​</a></h2><ol><li><strong>算力可插拔</strong>：core/ai 通过 MQ 下发任务，本地 compute-worker 与云端 compute-worker 是同一接口的不同实现，切换只需改 MQ 订阅方，不涉及架构重构</li><li><strong>播放源可切换</strong>：视频 URL 存相对路径，渲染时拼 endpoint；切云 CDN 只改拼接逻辑，不改服务拆分</li><li><strong>边界由三问决定</strong>：资源隔离、故障隔离、变更节奏——共享事务/身份核的数据不拆</li><li><strong>SSE 替代 WebSocket</strong>：单 HTTP 长流，易代理、易鉴权、NAT 友好</li><li><strong>PG 替代 ES</strong>：不要额外组件，PG FTS + zhparser 全文搜索 + pg_trgm 模糊/补全，零组件运维</li></ol><h2 id="_1-现状" tabindex="-1">1. 现状 <a class="header-anchor" href="#_1-现状" aria-label="Permalink to &quot;1. 现状&quot;">​</a></h2><h3 id="_1-1-java-事实源-6-个物理服务" tabindex="-1">1.1 Java 事实源（6 个物理服务） <a class="header-anchor" href="#_1-1-java-事实源-6-个物理服务" aria-label="Permalink to &quot;1.1 Java 事实源（6 个物理服务）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>端口</th><th>职责</th><th>备注</th></tr></thead><tbody><tr><td>gateway</td><td>8080</td><td>Spring Cloud Gateway，路由转发，Nacos 注册</td><td>用脚投票：ai/search 确实独立</td></tr><tr><td>account-social</td><td>8081</td><td>用户/角色/验证码/关注/隐私/审计/操作任务</td><td></td></tr><tr><td>video-media</td><td>8082</td><td>稿件/视频/分类/轮播/字幕/创作/统计</td><td>live/meeting 塞这里</td></tr><tr><td>content-interaction</td><td>8085</td><td>评论/弹幕/互动/收藏/历史/动态/消息/举报/审核/画像</td><td></td></tr><tr><td>search-recommend</td><td>8084</td><td>搜索/热榜/推荐/索引/创作者统计/运营工单</td><td>analytics 塞这里</td></tr><tr><td>ai</td><td>8088</td><td>AI 摘要/审核/客服/渠道/用量</td><td>有独立业务价值的服务</td></tr><tr><td>mq</td><td>—</td><td>消息 payload 公共库（非服务）</td><td></td></tr></tbody></table><h3 id="_1-2-go-单体现状" tabindex="-1">1.2 Go 单体现状 <a class="header-anchor" href="#_1-2-go-单体现状" aria-label="Permalink to &quot;1.2 Go 单体现状&quot;">​</a></h3><p>一个二进制 <code>core</code> 装 21 域：core/video/search/social/live/admin/ai/analytics/moderation/meeting/profile/studio/subtitle/support。进程内广播器（danmaku/notification）+ 内存 MQ + pg-fts + Redis 缓存。Makefile 已就位，产物落 <code>/tmp/</code>。</p><h3 id="_1-3-两版差距" tabindex="-1">1.3 两版差距 <a class="header-anchor" href="#_1-3-两版差距" aria-label="Permalink to &quot;1.3 两版差距&quot;">​</a></h3><ul><li><strong>该学的</strong>：ai、search 独立是真实资源边界</li><li><strong>不该抄的</strong>：account 与 interaction 分开、analytics 塞 search、live 塞 video-media——这些都是部署时的权宜，不是设计</li></ul><h2 id="_2-目标拓扑-1-核心-2-业务-1-算力" tabindex="-1">2. 目标拓扑：1 核心 + 2 业务 + 1 算力 <a class="header-anchor" href="#_2-目标拓扑-1-核心-2-业务-1-算力" aria-label="Permalink to &quot;2. 目标拓扑：1 核心 + 2 业务 + 1 算力&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>主控（大算力专用机）</span></span>
<span class="line"><span>├─ core (业务核心 :8080)</span></span>
<span class="line"><span>│    account + interaction + social + admin + moderation</span></span>
<span class="line"><span>│    + studio + subtitle + profile + support + video/稿件元数据</span></span>
<span class="line"><span>│    ├─ SSE 端点（订阅 Redis pub/sub 推给本节点客户端）</span></span>
<span class="line"><span>│    ├─ pg-fts 搜索入口</span></span>
<span class="line"><span>│    └─ gRPC/HTTP 出站调用，算力任务入 MQ</span></span>
<span class="line"><span>├─ ai (AI 业务服务 :8088)</span></span>
<span class="line"><span>│    摘要/审核/客服/技能/渠道/提示词/用量/缓存</span></span>
<span class="line"><span>│    ├─ 业务 API 暴露</span></span>
<span class="line"><span>│    └─ 向 MQ 下发 ai_* 算力任务，订阅结果落库</span></span>
<span class="line"><span>├─ search (搜索服务 :8084)</span></span>
<span class="line"><span>│    PG FTS(zhparser) + pg_trgm 热补全</span></span>
<span class="line"><span>│    推荐 SQL + 创作者统计 + 运营工单</span></span>
<span class="line"><span>│    索引重建定期任务，主控低峰执行</span></span>
<span class="line"><span>├─ compute-worker (算力，无端口，MQ 消费)</span></span>
<span class="line"><span>│    ffmpeg → HLS 分片 | Whisper → 字幕 | Ollama → 摘要/审核/客服</span></span>
<span class="line"><span>│    结果回写 MinIO / PG，进度事件回 MQ</span></span>
<span class="line"><span>└─ nginx :80 LB（到各 ARM 节点 core 实例）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ARM 节点（盒子 / 手机，全部跑服务）</span></span>
<span class="line"><span>└─ core 无状态实例 ×N</span></span>
<span class="line"><span>    ├─ JWT 自验，连主控的 PG/Redis/MinIO/MQ</span></span>
<span class="line"><span>    ├─ SSE 弹幕/通知（Redis pub/sub 全节点 fanout）</span></span>
<span class="line"><span>    └─ 任意节点被 nginx 路由到</span></span>
<span class="line"><span></span></span>
<span class="line"><span>共享件：PG（主控）· Redis · MinIO · MQ</span></span></code></pre></div><h2 id="_3-边界哲学" tabindex="-1">3. 边界哲学 <a class="header-anchor" href="#_3-边界哲学" aria-label="Permalink to &quot;3. 边界哲学&quot;">​</a></h2><p>拆不拆只问三个问题：</p><ol><li><strong>资源隔离</strong>：CPU/GPU/Mem 密集的活 → 拆（转码、AI 推理、索引重建）</li><li><strong>故障隔离</strong>：长连接/高并发/易崩形态 → 拆（live/meeting/SSE 流）</li><li><strong>变更节奏</strong>：schema/配置独立演进、需独立重启 → 拆</li></ol><p>共享事务、共享身份核的数据 → <strong>留在原地</strong>。</p><h3 id="逐域判定" tabindex="-1">逐域判定 <a class="header-anchor" href="#逐域判定" aria-label="Permalink to &quot;逐域判定&quot;">​</a></h3><table tabindex="0"><thead><tr><th>域</th><th style="text-align:center;">资源</th><th style="text-align:center;">故障</th><th style="text-align:center;">变更</th><th>判定</th></tr></thead><tbody><tr><td>compute-worker（ffmpeg/Whisper/Ollama）</td><td style="text-align:center;">★★★</td><td style="text-align:center;">★★★</td><td style="text-align:center;">★★★</td><td><strong>独立进程，无端口，MQ 驱动</strong></td></tr><tr><td>ai 业务</td><td style="text-align:center;">★</td><td style="text-align:center;">★★</td><td style="text-align:center;">★★★</td><td><strong>独立服务 :8088</strong></td></tr><tr><td>search/recommend</td><td style="text-align:center;">★★</td><td style="text-align:center;">★★</td><td style="text-align:center;">★★★</td><td><strong>独立服务 :8084</strong></td></tr><tr><td>live/meeting（SSE 化后）</td><td style="text-align:center;">★★</td><td style="text-align:center;">★★</td><td style="text-align:center;">★★</td><td>默认留 core，负载起来再抽</td></tr><tr><td>account + interaction + social</td><td style="text-align:center;">☆</td><td style="text-align:center;">☆</td><td style="text-align:center;">☆</td><td><strong>合并留 core</strong></td></tr><tr><td>admin/moderation/studio/subtitle/profile/support</td><td style="text-align:center;">☆</td><td style="text-align:center;">☆</td><td style="text-align:center;">☆</td><td>并入 core</td></tr></tbody></table><h2 id="_4-算力可插拔设计" tabindex="-1">4. 算力可插拔设计 <a class="header-anchor" href="#_4-算力可插拔设计" aria-label="Permalink to &quot;4. 算力可插拔设计&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>core/ai → MQ 任务（transcode / ai_summary / ai_review / extract_audio / generate_subtitle）</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>本地 compute-worker（ffmpeg + Ollama + Whisper）</span></span>
<span class="line"><span>       ↓ 切换只需：</span></span>
<span class="line"><span>云端 compute-worker（云转码 API + 云 LLM + 云 ASR）</span></span>
<span class="line"><span>       ↓ 或直接：</span></span>
<span class="line"><span>播放端直连云端 CDN（MinIO → 云存储，URL 拼接逻辑改一下）</span></span></code></pre></div><p><strong>MQ 接口 = 抽象层</strong>。本地 worker 和云端 worker 是同一 MQ task 类型的不同实现。core/ai 不关心谁在算。切换是 MQ 订阅方的配置变化，不是架构重构。</p><h2 id="_5-sse-替换-websocket" tabindex="-1">5. SSE 替换 WebSocket <a class="header-anchor" href="#_5-sse-替换-websocket" aria-label="Permalink to &quot;5. SSE 替换 WebSocket&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现 Java WS 通道</th><th>目标</th></tr></thead><tbody><tr><td><code>/ws/danmaku</code></td><td><code>POST /api/danmaku/send</code> + <code>GET /sse/danmaku?video_id=X</code>（已有）</td></tr><tr><td><code>/ws/notification</code></td><td><code>GET /sse/notify</code>（已有）</td></tr><tr><td><code>/ws/meeting</code> 信令</td><td>WebRTC 信令改 SSE + HTTP POST 往返</td></tr></tbody></table><p><strong>广播器外置化改造：</strong></p><ul><li><code>DanmakuBroadcaster</code>（进程内 map+chan）→ <strong>Redis pub/sub</strong></li><li><code>NotificationBroadcaster</code>（进程内 map+chan）→ <strong>Redis pub/sub</strong></li><li>任一节点收事件 → 发 redis → 所有 core 实例 SSE 推给本节点客户端</li></ul><h2 id="_6-pg-替代-es" tabindex="-1">6. PG 替代 ES <a class="header-anchor" href="#_6-pg-替代-es" aria-label="Permalink to &quot;6. PG 替代 ES&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>方案</th><th>状态</th></tr></thead><tbody><tr><td>全文检索</td><td><code>tsvector</code> + GIN 索引</td><td>已用 pg-fts</td></tr><tr><td>中文分词</td><td>zhparser 扩展 + textsearch_config</td><td>未做，需 docker PG 镜像编译 C 扩展</td></tr><tr><td>模糊/纠错/补全</td><td>pg_trgm GIN(gist)</td><td>未做</td></tr></tbody></table><p><strong>代价：</strong> zhparser 需在 PG 镜像里编译安装；中文切词效果上限取决于词典，需维护热词表。</p><h2 id="_7-横向前置改造清单-多实例-core-前的必选项" tabindex="-1">7. 横向前置改造清单（多实例 core 前的必选项） <a class="header-anchor" href="#_7-横向前置改造清单-多实例-core-前的必选项" aria-label="Permalink to &quot;7. 横向前置改造清单（多实例 core 前的必选项）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>当前</th><th>问题</th><th>改法</th><th>优先级</th></tr></thead><tbody><tr><td>MQ <code>Type:&quot;memory&quot;</code></td><td>各实例 MQ 独立，任务链跨实例丢失</td><td>Redis Streams / RabbitMQ</td><td>P0</td></tr><tr><td>弹幕广播器（进程内 map+chan）</td><td>连 core-A 看不到 core-B 的弹幕</td><td>Redis pub/sub</td><td>P0</td></tr><tr><td>通知广播器（进程内 map+chan）</td><td>同上</td><td>Redis pub/sub</td><td>P0</td></tr><tr><td>评论频控（内存 map+mutex）</td><td>多实例各自算账，防刷失效</td><td>Redis 计数</td><td>P1</td></tr><tr><td>PG 连接池 <code>MaxOpen=20</code></td><td>多实例叠加撞 PG 上限</td><td>按实例数调参 + PgBouncer</td><td>P1</td></tr><tr><td><code>handleSSEDanmaku:290</code> 直接订阅进程内 channel</td><td>随广播器一起改</td><td>随广播器改造</td><td>P0</td></tr></tbody></table><h2 id="_8-msg-danmaku-服务抽离方案" tabindex="-1">8. msg-danmaku 服务抽离方案 <a class="header-anchor" href="#_8-msg-danmaku-服务抽离方案" aria-label="Permalink to &quot;8. msg-danmaku 服务抽离方案&quot;">​</a></h2><h3 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h3><p>将弹幕（danmaku）+ 消息/通知（message）从 <code>internal/core/</code> 抽出为独立服务 <code>cmd/msg-danmaku/</code>，端口 <code>:8086</code>。</p><h3 id="新服务职责" tabindex="-1">新服务职责 <a class="header-anchor" href="#新服务职责" aria-label="Permalink to &quot;新服务职责&quot;">​</a></h3><ul><li>弹幕 CRUD + SSE 实时推流（<code>/sse/danmaku</code>）</li><li>消息/会话 CRUD + 通知 SSE 推流（<code>/sse/notify</code>）</li><li><code>DanmakuBroadcaster</code> / <code>NotificationBroadcaster</code>（进程内 map+chan，留在此服务，单实例够用）</li><li>独立 PG 连接</li></ul><h3 id="core-拿掉的内容" tabindex="-1">Core 拿掉的内容 <a class="header-anchor" href="#core-拿掉的内容" aria-label="Permalink to &quot;Core 拿掉的内容&quot;">​</a></h3><p>从 <code>internal/core/</code> 删除：</p><ul><li><code>danmaku_repository.go</code>（含 DanmakuBroadcaster、DanmakuEvent）</li><li><code>danmaku_service.go</code></li><li><code>message_repository.go</code>（含 MessageRepository、Conversation、Message、NotificationBroadcaster、NotificationEvent）</li><li><code>message_handler.go</code>（MessageHTTPHandler）</li><li><code>http_handler.go</code> 中所有 danmaku/message/SSE 路由</li></ul><h3 id="core-的改动" tabindex="-1">Core 的改动 <a class="header-anchor" href="#core-的改动" aria-label="Permalink to &quot;Core 的改动&quot;">​</a></h3><p><strong>问题：</strong> <code>comment_service.go</code> 和 <code>interaction_service.go</code> 通过 <code>messageRepo.DB()</code> 拿 <code>*sql.DB</code> 查非 message 表，同时调 <code>messageRepo.SendMessage()</code> 发通知。</p><p><strong>改法：</strong></p><ol><li><code>messageRepo.DB()</code> → 直接给 comment/interaction service 传 <code>*sql.DB</code>（本来就该有的依赖）</li><li><code>messageRepo.SendMessage()</code> → 改为发布 MQ 事件（<code>comment-reply</code> / <code>like</code> 等），msg-danmaku 服务消费后落库 + SSE 推</li></ol><p><strong>通信方式：MQ（异步解耦）。</strong> core 不关心通知何时送达，msg-danmaku 消费 MQ 事件后自行落库和 SSE 推流。</p><h3 id="实施步骤" tabindex="-1">实施步骤 <a class="header-anchor" href="#实施步骤" aria-label="Permalink to &quot;实施步骤&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步</th><th>内容</th></tr></thead><tbody><tr><td>1</td><td>新建 <code>internal/msg-danmaku/</code>，从 <code>internal/core/</code> 搬入 danmaku + message 代码，拆成独立包</td></tr><tr><td>2</td><td>新建 <code>cmd/msg-danmaku/main.go</code>，启动 HTTP 服务 <code>:8086</code></td></tr><tr><td>3</td><td>给 <code>comment_service.go</code> / <code>interaction_service.go</code> 直接传 <code>*sql.DB</code>，去掉 <code>messageRepo.DB()</code></td></tr><tr><td>4</td><td><code>sendLikeNotification</code> / <code>sendReplyNotification</code> / <code>sendCommentLikeNotification</code> 改为发 MQ 事件</td></tr><tr><td>5</td><td>msg-danmaku 订阅 MQ 事件，落库 message + SSE 推</td></tr><tr><td>6</td><td>从 core 的 HTTP handler 中去掉 danmaku/message/SSE 路由注册</td></tr><tr><td>7</td><td>更新 Makefile 加 <code>build-msg-danmaku</code> target</td></tr><tr><td>8</td><td>验证：弹幕发送 → SSE 收到；评论回复 → 通知 SSE 收到</td></tr></tbody></table><h2 id="_9-分阶段迁移-更新版" tabindex="-1">9. 分阶段迁移（更新版） <a class="header-anchor" href="#_9-分阶段迁移-更新版" aria-label="Permalink to &quot;9. 分阶段迁移（更新版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th><th>验收</th></tr></thead><tbody><tr><td><strong>P0</strong>（已完）</td><td>Makefile 统一构建；二进制落 /tmp；media 独立进程</td><td><code>make build</code> 出 core+media</td></tr><tr><td><strong>P1</strong></td><td>media → compute-worker 定型（MQ 任务类型表 + 无端口 + 进度回传）</td><td>盒子跑 worker 能接到转码任务</td></tr><tr><td><strong>P2</strong></td><td>PG FTS 中文分词落地（zhparser/trigram）</td><td>中文搜索返回正确结果</td></tr><tr><td><strong>P3</strong></td><td>SSE 迁移：弹幕/通知/会议信令，广播器改 Redis pub/sub</td><td>全网 SSE 正常，WS 通道下架</td></tr><tr><td><strong>P4</strong></td><td>ai 服务抽离（搬 internal/ai → cmd/ai + :8088，Ollama 交给 worker）</td><td>ai 独立进程跑，core 走 API/MQ</td></tr><tr><td><strong>P5</strong></td><td>search 抽离（:8084）</td><td>搜索/热榜/推荐独立进程</td></tr><tr><td><strong>P6</strong></td><td>msg-danmaku 抽离（:8086，MQ 驱动通知）</td><td>弹幕/消息独立服务，core 不再直连 message 表</td></tr><tr><td><strong>P7</strong></td><td>nginx LB + 多 core 实例横向</td><td>ARM 节点各跑 core，nginx 轮询</td></tr></tbody></table><h2 id="_10-验收标准-整体" tabindex="-1">10. 验收标准（整体） <a class="header-anchor" href="#_10-验收标准-整体" aria-label="Permalink to &quot;10. 验收标准（整体）&quot;">​</a></h2><ul><li>任意 ARM 节点冷启动 → 注册 core 实例 → 从 nginx 接到请求</li><li>主控 core 重启，弹幕/通知不丢不重（Redis pub/sub 兜底）</li><li>不加 ES/不加 WS，PG 一家把搜索与推荐跑通</li><li><code>make build</code> 一次出全部 4 个二进制：core / ai / search / compute-worker</li><li>MQ 切换：将 compute-worker 的订阅从&quot;本地&quot;改为&quot;云端&quot;，不碰 core/ai 代码</li></ul>`,49)])])}const m=e(n,[["render",o]]);export{g as __pageData,m as default};
